import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.ArrayList; import java.util.Collections; import java.util.List; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int r = Integer.parseInt(st.nextToken()); int c = Integer.parseInt(st.nextToken()); char[][] grid = new char[r][c]; for (int i = 0; i < r; i++) { String row = br.readLine(); for (int j = 0; j < c; j++) { grid[i][j] = row.charAt(j); } } List<Integer> areas = new ArrayList<>(); for (int i = 0; i < r; i++) { for (int j = 0; j < c; j++) { if (grid[i][j] == '.') { areas.add(dfs(grid, i, j, r, c)); } } } Collections.sort(areas); System.out.println(areas.size()); StringBuilder sb = new StringBuilder(); for (int area : areas) { sb.append(area).append(" "); } System.out.println(sb.toString().trim()); } } private static int dfs(char[][] grid, int i, int j, int r, int c) { if (i < 0 || i >= r || j < 0 || j >= c || grid[i][j] != '.') { return 0; } grid[i][j] = '#'; int count = 1; count += dfs(grid, i + 1, j, r, c); count += dfs(grid, i - 1, j, r, c); count += dfs(grid, i, j + 1, r, c); count += dfs(grid, i, j - 1, r, c); return count; } }